<template><el-dialog title="补拉订单与售后数据" :visible.sync="visible" width="760px" append-to-body :close-on-click-modal="false"><el-alert title="补拉使用独立任务，不回退自动同步进度；同步售后申请不会自动同意或改变库存。" type="info" :closable="false" /><el-form :disabled="saving" label-width="140px" style="margin-top:20px"><el-form-item label="业务类型" required><el-radio-group v-model="kind" @change="changed"><el-radio-button v-for="t in types" :key="t" :label="t">{{ names[t] }}</el-radio-button></el-radio-group></el-form-item><el-form-item label="店铺" required><el-select v-model="channel" filterable style="width:100%"><el-option v-for="c in channels.filter(c=>Number(c.enabled))" :key="c.channel_id" :value="c.channel_id" :label="c.channel_name" /></el-select></el-form-item><el-form-item label="补拉方式"><el-radio-group v-model="mode" @change="changed"><el-radio label="TIME">按更新时间</el-radio><el-radio label="IDS">指定单号</el-radio></el-radio-group></el-form-item><el-form-item v-if="mode==='TIME'" :label="kind==='EXCHANGE' ? '平台修改时间' : '推送库更新时间'" required><el-date-picker v-model="range" type="datetimerange" value-format="yyyy-MM-dd HH:mm:ss" range-separator="至" style="width:100%" /><p class="hint">{{ kind==='EXCHANGE' ? '最多31天，调用平台换货查询接口。' : '最多90天，只读取本店铺推送库。' }}</p></el-form-item><el-form-item v-else :label="numberLabel" required><el-input v-model="numbers" type="textarea" :rows="5" maxlength="10000" :placeholder="`填写完整${numberLabel}，换行或逗号分隔；最多${limit}个`" /><p class="hint">{{ kind==='ORDER' ? '填写 tid' : kind==='REFUND' ? '填写 refund_id，不是订单 tid' : '填写 dispute_id，不是订单 tid' }}；单号全程按文本处理。</p></el-form-item></el-form><span slot="footer"><el-button :disabled="saving" @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交补拉</el-button></span></el-dialog></template>
<script>
import { backfillOrders } from '@/api/order'
import { syncRefund } from '@/api/order/refund'
import { exchangeSync } from '@/api/order/exchange'
import { parseTime } from '@/utils/ruoyi'
import { intakeKinds } from './intakePresentation'
const key = () => `INTAKE_${Date.now()}_${Math.random().toString(36).slice(2)}`
export default { name: 'IntakeBackfill', props: { channels: Array, types: Array }, data: () => ({ visible: false, saving: false, kind: '', channel: null, mode: 'TIME', range: [], numbers: '', requestKey: '', names: intakeKinds }), computed: { numberLabel() { return this.kind==='ORDER' ? '平台订单号' : this.kind==='REFUND' ? '平台退款单号' : '平台换货单号' }, limit() { return this.kind==='ORDER' ? 100 : this.kind==='REFUND' ? 50 : 20 } }, watch: { kind() { this.changed() }, channel() { this.changed() }, range() { this.changed() }, numbers() { this.changed() } }, methods: {
  open(kind, channel) { this.kind = this.types.includes(kind) ? kind : this.types[0]; this.channel = channel || null; this.mode = 'TIME'; this.numbers = ''; this.range = [parseTime(new Date(Date.now()-86400000)),parseTime(new Date())]; this.changed(); this.visible = true }, changed() { if (!this.saving) this.requestKey=key() },
  async submit() { if (this.saving) return; if (!this.channel || !this.types.includes(this.kind)) return this.$message.warning('请选择业务类型和店铺'); let values=[]; if (this.mode==='IDS') { values=Array.from(new Set(this.numbers.trim().split(/[\s,，;；]+/).filter(Boolean))); const maxDigits=this.kind==='ORDER' ? 19 : this.kind==='REFUND' ? 20 : 64; if (!values.length || values.length>this.limit || values.some(v=>!new RegExp(`^[1-9][0-9]{0,${maxDigits-1}}$`).test(v))) return this.$message.warning(`请填写1至${this.limit}个完整${this.numberLabel}`) } else if (!this.range || this.range.length!==2 || this.range[0]>=this.range[1]) return this.$message.warning('请选择开始早于结束的时间范围'); this.saving=true; try { const common={channel_id:this.channel,request_key:this.requestKey,start_time:(this.range||[])[0],end_time:(this.range||[])[1]}; let result; if(this.kind==='ORDER') result=await backfillOrders({...common,channel_ids:[this.channel],mode:this.mode==='IDS'?'TID':'TIME',tids:values}); else if(this.kind==='REFUND') result=await syncRefund({...common,mode:this.mode==='IDS'?'IDS':'MANUAL',refund_ids:values}); else result=await exchangeSync({...common,dispute_ids:this.mode==='IDS'?values.join('\n'):''}); this.visible=false;this.$message.success('补拉任务已提交，可在同步任务查看逐条结果');this.$emit('submitted',{kind:this.kind,data:result.data}) } finally { this.saving=false } }
} }
</script>
<style scoped>.hint{font-size:12px;color:#8290a4;line-height:1.8;margin:6px 0 0}</style>
